private Frame parse(byte[] payload, int p, int level, int fs) {
    int b0 = payload[p] & 255;
    int width = 1 << (b0 >>> 6);
    if (width > payload.length - p) {
        throw new WireException(FRAME_ENCODING_ERROR, fs);
    }
    long type = b0 & 0x3fL;
    for (int i = 1; i < width; i++) {
        type = (type << 8) | (payload[p + i] & 255L);
    }
    if (width != 1 || !KNOWN[(int) type]) {
        throw new WireException(FRAME_ENCODING_ERROR, fs);
    }
    if (type == 0x07 || type == 0x1e) {
        throw new WireException(PROTOCOL_VIOLATION, fs);
